// ZagBench – BeFannkuch (JavaScript port of BeFannkuch.class.st).
//
// Fannkuch-Redux: count pancake flips across all permutations of 0..n-1.
// Permutations generated by the rotation-based algorithm (Benchmark Game
// reference) so that checksum signs alternate correctly with permutation order.
'use strict';

const { Benchmark } = require('./benchmark');

// Verification table (checksum, maxFlips) for n = 1..11, indexed by n-1
const EXPECTED = [
  [0,      0],   // n=1
  [-1,     1],   // n=2
  [2,      2],   // n=3
  [4,      4],   // n=4
  [11,     7],   // n=5
  [49,     10],  // n=6
  [228,    16],  // n=7
  [1616,   22],  // n=8
  [8629,   30],  // n=9
  [73196,  38],  // n=10
  [556355, 51],  // n=11
];

class BeFannkuch extends Benchmark {
  static get mainIterations()  { return 2; }
  static get innerIterations() { return 10; }

  innerBenchmarkLoop(iterations) {
    return this._verify(this._solve(iterations), iterations);
  }

  _solve(n) {
    const perm1 = new Array(n);  // [0, ..., n-1]
    const count = new Array(n);  // [1, ..., n]
    const perm  = new Array(n);
    for (let i = 0; i < n; i++) { perm1[i] = i; count[i] = i + 1; }
    let checksum  = 0;
    let maxCount  = 0;
    let nperm     = 0;

    for (;;) {
      // Process current permutation
      let flips = 0;
      if (perm1[0] !== 0) {
        for (let i = 0; i < n; i++) perm[i] = perm1[i];
        while (perm[0] !== 0) {
          const k = perm[0];
          let lo = 0, hi = k;
          while (lo < hi) {
            const tmp = perm[lo]; perm[lo] = perm[hi]; perm[hi] = tmp;
            lo++; hi--;
          }
          flips++;
        }
        if (flips > maxCount) maxCount = flips;
      }

      checksum += (nperm % 2 === 0) ? flips : -flips;
      nperm++;

      // Advance to the next permutation via left-rotation
      let r = 1;
      for (;;) {
        const perm0 = perm1[0];
        for (let i = 0; i < r; i++) perm1[i] = perm1[i + 1];
        perm1[r] = perm0;
        count[r]--;
        if (count[r] > 0) {
          break;
        } else {
          count[r] = r + 1;  // reset
          r++;
          if (r >= n) return [checksum, maxCount];
        }
      }
    }
  }

  _verify(result, iterations) {
    if (iterations < 1 || iterations > 11) {
      process.stdout.write(`No verification result for ${iterations} found\n`);
      return false;
    }
    const expected = EXPECTED[iterations - 1];
    return result[0] === expected[0] && result[1] === expected[1];
  }
}

module.exports = { BeFannkuch };
